/*
 * A257983  Sequence (a(n)) generated by Rule 3 (in Comments) with a(1) = 1
 *          and d(1) = 2.
 * https://oeis.org/A257983
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 168, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A257983:  a(n) generated by Rule 3 with a(1)=1, d(1)=2 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* internal storage for the sequence */
static int64_t *a_vals      = NULL;   /* stored a-values, index 0 corresponds to a(1) */
static size_t  a_cap       = 0;       /* capacity of a_vals */
static bool    *a_used     = NULL;   /* a_used[v] == true iff value v has already occurred */
static size_t  a_used_cap  = 0;       /* capacity of a_used */
static bool    *d_pos      = NULL;   /* d_pos[h] == true iff positive difference h has occurred */
static size_t  d_pos_cap   = 0;       /* capacity of d_pos (indices 0 .. d_pos_cap-1) */
static bool    *d_neg      = NULL;   /* d_neg[h] == true iff negative difference -h has occurred */
static size_t  d_neg_cap   = 0;       /* capacity of d_neg (indices 0 .. d_neg_cap-1) */
static size_t  used_len    = 0;       /* number of generated terms so far */

/*---------- helpers for growing dynamic arrays ----------*/
static void ensure_a_cap(size_t need)
{
    if (need <= a_cap) return;
    size_t new_cap = a_cap ? a_cap * 2 : 16;
    while (new_cap < need) new_cap *= 2;
    int64_t *tmp = (int64_t *)realloc(a_vals, new_cap * sizeof(int64_t));
    if (!tmp) exit(EXIT_FAILURE);
    a_vals = tmp;
    a_cap = new_cap;
}

static void ensure_a_used_cap(size_t need)
{
    if (need <= a_used_cap) return;
    size_t new_cap = a_used_cap ? a_used_cap * 2 : 16;
    while (new_cap < need) new_cap *= 2;
    bool *tmp = (bool *)realloc(a_used, new_cap * sizeof(bool));
    if (!tmp) exit(EXIT_FAILURE);
    /* initialise new slots to false */
    for (size_t i = a_used_cap; i < new_cap; ++i) tmp[i] = false;
    a_used = tmp;
    a_used_cap = new_cap;
}

static void ensure_d_pos_cap(size_t need)
{
    if (need <= d_pos_cap) return;
    size_t new_cap = d_pos_cap ? d_pos_cap * 2 : 16;
    while (new_cap < need) new_cap *= 2;
    bool *tmp = (bool *)realloc(d_pos, new_cap * sizeof(bool));
    if (!tmp) exit(EXIT_FAILURE);
    for (size_t i = d_pos_cap; i < new_cap; ++i) tmp[i] = false;
    d_pos = tmp;
    d_pos_cap = new_cap;
}

static void ensure_d_neg_cap(size_t need)
{
    if (need <= d_neg_cap) return;
    size_t new_cap = d_neg_cap ? d_neg_cap * 2 : 16;
    while (new_cap < need) new_cap *= 2;
    bool *tmp = (bool *)realloc(d_neg, new_cap * sizeof(bool));
    if (!tmp) exit(EXIT_FAILURE);
    for (size_t i = d_neg_cap; i < new_cap; ++i) tmp[i] = false;
    d_neg = tmp;
    d_neg_cap = new_cap;
}

/* mark that a value has appeared in A(k) */
static void mark_A(int64_t val)
{
    if (val <= 0) return;
    size_t idx = (size_t)val;
    ensure_a_used_cap(idx + 1);
    a_used[idx] = true;
}

/* initialise the sequence with a(1)=1 and d(1)=2 */
static void init_sequence(void)
{
    a_cap = 16;
    a_vals = (int64_t *)calloc(a_cap, sizeof(int64_t));
    if (!a_vals) exit(EXIT_FAILURE);

    a_used_cap = 16;
    a_used = (bool *)calloc(a_used_cap, sizeof(bool));
    if (!a_used) exit(EXIT_FAILURE);

    d_pos_cap = 16;
    d_pos = (bool *)calloc(d_pos_cap, sizeof(bool));
    if (!d_pos) exit(EXIT_FAILURE);

    d_neg_cap = 16;
    d_neg = (bool *)calloc(d_neg_cap, sizeof(bool));
    if (!d_neg) exit(EXIT_FAILURE);

    a_vals[0] = 1;          /* a(1) */
    mark_A(1);
    ensure_d_pos_cap(2);
    d_pos[2] = true;        /* d(1) = 2 */
    used_len = 1;
}

/* generate the sequence up to index "upto" (1‑based) */
static void generate_until(idx_t upto)
{
    while (used_len < (size_t)upto)
    {
        int64_t a_k = a_vals[used_len - 1];   /* current a(k) */
        int64_t low   = 1 - a_k;              /* lower bound of h in Step 1 */
        int64_t start = low + 1;              /* first integer > low */
        int64_t h = 0;
        bool found = false;

        /* Step 1: try negative h */
        for (int64_t cand = start; cand < 0; ++cand)
        {
            bool inD = false;
            if (cand > 0) {
                inD = (cand < (int64_t)d_pos_cap) && d_pos[(size_t)cand];
            } else { /* cand < 0 */
                size_t idx = (size_t)(-cand);
                inD = (idx < d_neg_cap) && d_neg[idx];
            }
            if (inD) continue;

            int64_t target = a_k + cand;        /* a(k)+h */
            if (target > 0 && target <= (int64_t)a_used_cap-1 && a_used[(size_t)target]) continue;

            h = cand;
            found = true;
            break;
        }

        /* Step 2: if no h found in Step 1 */
        if (!found)
        {
            for (int64_t cand = 1; ; ++cand)
            {
                bool inD = false;
                if (cand < d_pos_cap) inD = d_pos[(size_t)cand];
                if (inD) continue;

                int64_t target = a_k - cand;    /* a(k)-h */
                if (target > 0 && target <= (int64_t)a_used_cap-1 && a_used[(size_t)target]) continue;

                h = cand;
                break;
            }
        }

        int64_t a_next = a_k + h;

        /* store new terms */
        ensure_a_cap(used_len + 1);
        a_vals[used_len] = a_next;

        if (h > 0)
        {
            ensure_d_pos_cap((size_t)h + 1);
            d_pos[(size_t)h] = true;
        }
        else if (h < 0)
        {
            size_t idx = (size_t)(-h);
            ensure_d_neg_cap(idx + 1);
            d_neg[idx] = true;
        }

        /* mark a_next as used */
        if (a_next > 0) mark_A(a_next);

        ++used_len;
    }
}

/* public interface required by the test harness */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* out‑of‑range handling */
    if (!a_vals) init_sequence();  /* lazy initialisation */

    if ((size_t)n > used_len)
        generate_until(n);

    return (seq_t)a_vals[n - 1];
}
